package com.italiano2774.nativeapp;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.LocalDate;import java.util.*;
/** Keeps up to five private on-device JSON snapshots. No network and no external permission. */
public final class LocalBackupManager{
 private LocalBackupManager(){}private static File dir(Context c){File d=new File(c.getFilesDir(),"study_backups");if(!d.exists())d.mkdirs();return d;}
 public static void ensureVersionBackup(Context c,WordRepository repo,ProgressStore p,String version){ensureVersionBackupThen(c,repo,p,version,null);}
 public static void ensureVersionBackupThen(Context c,WordRepository repo,ProgressStore p,String version,Runnable after){android.content.SharedPreferences sp=c.getSharedPreferences("zhongxue_backup_meta",Context.MODE_PRIVATE);String key="version_backup_"+version;if(sp.getBoolean(key,false)){if(after!=null)after.run();return;}final Context app=c.getApplicationContext();new Thread(()->{try{if(p.introducedCount(repo.all())>0||p.dailyActivity(LocalDate.now())>0)create(app,repo,p);sp.edit().putBoolean(key,true).apply();}catch(Exception ignored){}finally{if(after!=null)try{after.run();}catch(Exception ignored){}}},"version-backup").start();}
 public static void maybeBackup(Context c,WordRepository repo,ProgressStore p){String today=LocalDate.now().toString();android.content.SharedPreferences sp=c.getSharedPreferences("italiano2774_native",Context.MODE_PRIVATE);if(today.equals(sp.getString("last_auto_backup_day",""))||p.dailyActivity(LocalDate.now())==0)return;final Context app=c.getApplicationContext();new Thread(()->{try{create(app,repo,p);sp.edit().putString("last_auto_backup_day",today).apply();}catch(Exception ignored){}}).start();}
 public static void createAsync(Context c,WordRepository repo,ProgressStore p,boolean force){final Context app=c.getApplicationContext();new Thread(()->{try{create(app,repo,p); }catch(Exception ignored){}}).start();}
 public static File create(Context c,WordRepository repo,ProgressStore p)throws Exception{JSONObject root=p.exportJson(repo.all());JSONArray custom=new JSONArray();LearningDatabase db=LearningDatabase.get(c);for(CustomStudyItem x:db.customStudyItemDao().all()){JSONObject o=new JSONObject();o.put("kind",x.kind);o.put("italian",x.italian);o.put("chinese",x.chinese);o.put("note",x.note);o.put("createdAt",x.createdAt);o.put("dueEpochDay",x.dueEpochDay);o.put("intervalDays",x.intervalDays);o.put("attempts",x.attempts);o.put("correct",x.correct);o.put("stability",x.stability);o.put("difficulty",x.difficulty);custom.put(o);}root.put("customItems",custom);JSONArray errors=new JSONArray();for(ErrorRecordEntity er:db.learningStateDao().recentErrors(500)){JSONObject eo=new JSONObject();eo.put("createdAt",er.createdAt);eo.put("wordId",er.wordId);eo.put("mode",er.mode);eo.put("cause",er.cause);eo.put("expected",er.expected);eo.put("actual",er.actual);eo.put("detail",er.detail);errors.put(eo);}root.put("errorHistory",errors);JSONArray sentences=new JSONArray();for(SentenceProgressEntity sp:db.learningStateDao().recentSentences(2000)){JSONObject so=new JSONObject();so.put("sentenceId",sp.sentenceId);so.put("source",sp.source);so.put("italian",sp.italian);so.put("chinese",sp.chinese);so.put("attempts",sp.attempts);so.put("correct",sp.correct);so.put("lastEpochDay",sp.lastEpochDay);so.put("dueEpochDay",sp.dueEpochDay);so.put("intervalDays",sp.intervalDays);so.put("stability",sp.stability);so.put("difficulty",sp.difficulty);so.put("updatedAt",sp.updatedAt);so.put("meaningLevel",sp.meaningLevel);so.put("listeningLevel",sp.listeningLevel);so.put("recallLevel",sp.recallLevel);so.put("speakingLevel",sp.speakingLevel);so.put("lapses",sp.lapses);so.put("lastScore",sp.lastScore);sentences.put(so);}root.put("sentenceProgress",sentences);JSONArray grammar=new JSONArray();for(GrammarPoint gp:GrammarDiagnostics.all()){GrammarProgressEntity g=db.learningStateDao().grammar(gp.id);if(g==null)continue;JSONObject go=new JSONObject();go.put("grammarId",g.grammarId);go.put("attempts",g.attempts);go.put("correct",g.correct);go.put("lastEpochDay",g.lastEpochDay);go.put("dueEpochDay",g.dueEpochDay);go.put("intervalDays",g.intervalDays);go.put("stability",g.stability);go.put("difficulty",g.difficulty);go.put("updatedAt",g.updatedAt);grammar.put(go);}root.put("grammarProgress",grammar);JSONArray skills=new JSONArray();for(SkillProgressEntity sk:db.learningStateDao().allSkills()){JSONObject ko=new JSONObject();ko.put("skillId",sk.skillId);ko.put("attempts",sk.attempts);ko.put("correct",sk.correct);ko.put("responseMs",sk.responseMs);ko.put("lastEpochDay",sk.lastEpochDay);ko.put("updatedAt",sk.updatedAt);skills.put(ko);}root.put("skillProgress",skills);root.put("localBackupCreatedAt",System.currentTimeMillis());File f=new File(dir(c),"backup_"+System.currentTimeMillis()+".json");try(OutputStream out=new FileOutputStream(f)){out.write(root.toString().getBytes(StandardCharsets.UTF_8));}trim(c);return f;}
 public static List<File> list(Context c){File[] fs=dir(c).listFiles((d,n)->n.endsWith(".json"));List<File> out=fs==null?new ArrayList<>():new ArrayList<>(Arrays.asList(fs));out.sort((a,b)->Long.compare(b.lastModified(),a.lastModified()));return out;}
 public static File latest(Context c){List<File> x=list(c);return x.isEmpty()?null:x.get(0);}public static int count(Context c){return list(c).size();}
 public static String latestLabel(Context c){File f=latest(c);if(f==null)return "尚无本地备份";return "最近备份："+new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",java.util.Locale.CHINA).format(new java.util.Date(f.lastModified()))+" · 共 "+count(c)+" 份";}
 public static void appendAdvancedProgress(Context c,JSONObject root)throws Exception{LearningDatabase db=LearningDatabase.get(c);JSONArray sentences=new JSONArray();for(SentenceProgressEntity sp:db.learningStateDao().recentSentences(2000)){JSONObject so=new JSONObject();so.put("sentenceId",sp.sentenceId);so.put("source",sp.source);so.put("italian",sp.italian);so.put("chinese",sp.chinese);so.put("attempts",sp.attempts);so.put("correct",sp.correct);so.put("lastEpochDay",sp.lastEpochDay);so.put("dueEpochDay",sp.dueEpochDay);so.put("intervalDays",sp.intervalDays);so.put("stability",sp.stability);so.put("difficulty",sp.difficulty);so.put("updatedAt",sp.updatedAt);so.put("meaningLevel",sp.meaningLevel);so.put("listeningLevel",sp.listeningLevel);so.put("recallLevel",sp.recallLevel);so.put("speakingLevel",sp.speakingLevel);so.put("lapses",sp.lapses);so.put("lastScore",sp.lastScore);sentences.put(so);}root.put("sentenceProgress",sentences);JSONArray grammar=new JSONArray();for(GrammarPoint gp:GrammarDiagnostics.all()){GrammarProgressEntity g=db.learningStateDao().grammar(gp.id);if(g==null)continue;JSONObject go=new JSONObject();go.put("grammarId",g.grammarId);go.put("attempts",g.attempts);go.put("correct",g.correct);go.put("lastEpochDay",g.lastEpochDay);go.put("dueEpochDay",g.dueEpochDay);go.put("intervalDays",g.intervalDays);go.put("stability",g.stability);go.put("difficulty",g.difficulty);go.put("updatedAt",g.updatedAt);grammar.put(go);}root.put("grammarProgress",grammar);JSONArray skills=new JSONArray();for(SkillProgressEntity sk:db.learningStateDao().allSkills()){JSONObject ko=new JSONObject();ko.put("skillId",sk.skillId);ko.put("attempts",sk.attempts);ko.put("correct",sk.correct);ko.put("responseMs",sk.responseMs);ko.put("lastEpochDay",sk.lastEpochDay);ko.put("updatedAt",sk.updatedAt);skills.put(ko);}root.put("skillProgress",skills);}
 public static void restoreRoomExtras(Context c,JSONObject root)throws Exception{LearningDatabase db=LearningDatabase.get(c);JSONArray sentences=root.optJSONArray("sentenceProgress");if(sentences!=null){db.learningStateDao().clearSentences();for(int i=0;i<sentences.length();i++){JSONObject o=sentences.getJSONObject(i);SentenceProgressEntity x=new SentenceProgressEntity();x.sentenceId=o.optString("sentenceId");x.source=o.optString("source");x.italian=o.optString("italian");x.chinese=o.optString("chinese");x.attempts=o.optInt("attempts");x.correct=o.optInt("correct");x.lastEpochDay=o.optLong("lastEpochDay",Long.MIN_VALUE);x.dueEpochDay=o.optLong("dueEpochDay",Long.MIN_VALUE);x.intervalDays=o.optInt("intervalDays");x.stability=o.optDouble("stability",1.0);x.difficulty=o.optDouble("difficulty",5.0);x.updatedAt=o.optLong("updatedAt",System.currentTimeMillis());x.meaningLevel=o.optInt("meaningLevel",0);x.listeningLevel=o.optInt("listeningLevel",0);x.recallLevel=o.optInt("recallLevel",0);x.speakingLevel=o.optInt("speakingLevel",0);x.lapses=o.optInt("lapses",0);x.lastScore=o.optInt("lastScore",0);if(!x.sentenceId.isEmpty())db.learningStateDao().upsertSentence(x);}}JSONArray grammar=root.optJSONArray("grammarProgress");if(grammar!=null){db.learningStateDao().clearGrammar();for(int i=0;i<grammar.length();i++){JSONObject o=grammar.getJSONObject(i);GrammarProgressEntity x=new GrammarProgressEntity();x.grammarId=o.optString("grammarId");x.attempts=o.optInt("attempts");x.correct=o.optInt("correct");x.lastEpochDay=o.optLong("lastEpochDay",Long.MIN_VALUE);x.dueEpochDay=o.optLong("dueEpochDay",Long.MIN_VALUE);x.intervalDays=o.optInt("intervalDays");x.stability=o.optDouble("stability",1.0);x.difficulty=o.optDouble("difficulty",5.0);x.updatedAt=o.optLong("updatedAt",System.currentTimeMillis());if(!x.grammarId.isEmpty())db.learningStateDao().upsertGrammar(x);}}JSONArray skills=root.optJSONArray("skillProgress");if(skills!=null){db.learningStateDao().clearSkills();for(int i=0;i<skills.length();i++){JSONObject o=skills.getJSONObject(i);SkillProgressEntity x=new SkillProgressEntity();x.skillId=o.optString("skillId");x.attempts=o.optInt("attempts");x.correct=o.optInt("correct");x.responseMs=o.optLong("responseMs");x.lastEpochDay=o.optLong("lastEpochDay",Long.MIN_VALUE);x.updatedAt=o.optLong("updatedAt",System.currentTimeMillis());if(!x.skillId.isEmpty())db.learningStateDao().upsertSkill(x);}}}
 public static JSONObject read(File f)throws Exception{StringBuilder sb=new StringBuilder();try(BufferedReader br=new BufferedReader(new InputStreamReader(new FileInputStream(f),StandardCharsets.UTF_8))){String line;while((line=br.readLine())!=null)sb.append(line);}return new JSONObject(sb.toString());}
 private static void trim(Context c){List<File> x=list(c);for(int i=5;i<x.size();i++)x.get(i).delete();}
}
